export interface Receipt { id: number; tenant: string; key: string; cents: number }

function isNonEmptyToken(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

export class Ledger {
  readonly entries: Receipt[] = [];
  // Nested maps keep tenant and key namespaces separate, so no separator can
  // collide between ("a\x00b", "c") and ("a", "b\x00c") style inputs.
  private readonly receiptsByTenant = new Map<string, Map<string, Receipt>>();

  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    if (!isNonEmptyToken(tenant) || !isNonEmptyToken(key) || !Number.isInteger(cents) || cents <= 0) {
      throw new Error('invalid payment');
    }
    let receipts = this.receiptsByTenant.get(tenant);
    if (receipts === undefined) {
      receipts = new Map<string, Receipt>();
      this.receiptsByTenant.set(tenant, receipts);
    }
    const existing = receipts.get(key);
    if (existing !== undefined) {
      // Same tenant/key with a different amount must never debit again.
      if (existing.cents === cents) return existing;
      throw new Error('key conflict');
    }
    const receipt: Receipt = { id: this.entries.length + 1, tenant, key, cents };
    // All checks and mutations happen synchronously before the first await, so
    // concurrent callers serialize here and cannot double-debit.
    this.entries.push(receipt);
    receipts.set(key, receipt);
    return receipt;
  }
}
