import { Ledger, Receipt } from './ledger';
import { Transient, Transport } from './transport';

const MIN_ATTEMPTS = 1;
const MAX_ATTEMPTS = 5;

function isNonEmptyToken(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0;
}

export class PaymentService {
  constructor(private readonly ledger: Ledger, private readonly transport: Transport) {}

  async pay(tenant: string, key: string, cents: number, attempts = 3): Promise<Receipt> {
    // Validate before any ledger or transport action.
    if (
      !isNonEmptyToken(tenant) ||
      !isNonEmptyToken(key) ||
      !Number.isInteger(cents) ||
      cents <= 0 ||
      !Number.isInteger(attempts) ||
      attempts < MIN_ATTEMPTS ||
      attempts > MAX_ATTEMPTS
    ) {
      throw new Error('invalid payment');
    }

    // The debit happens at most once: once a receipt exists, retries only
    // re-acknowledge that exact receipt, so no duplicate debit is possible even
    // if the injected ledger is not idempotent itself.
    let receipt: Receipt | undefined;
    let lastError: unknown;
    for (let tryNumber = 1; tryNumber <= attempts; tryNumber++) {
      try {
        if (receipt === undefined) {
          const current = await this.ledger.apply(tenant, key, cents);
          receipt = current;
          await this.transport.acknowledge(current);
          return current;
        }
        const current: Receipt = receipt;
        await this.transport.acknowledge(current);
        return current;
      } catch (error) {
        lastError = error;
        if (!(error instanceof Transient)) throw error;
      }
    }
    // Retries exhausted on Transient: rethrow the final exception unchanged.
    throw lastError;
  }
}
EOF
