const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  // Ledger: repeated equal amount returns the original receipt; conflict throws without debit.
  const ledger = new Ledger();
  const first = await ledger.apply('shop', 'sale', 123);
  assert.deepEqual(await ledger.apply('shop', 'sale', 123), first);
  assert.equal(ledger.entries.length, 1);
  await assert.rejects(() => ledger.apply('shop', 'sale', 456),
    e => e instanceof Error && e.message === 'key conflict');
  assert.equal(ledger.entries.length, 1);
  assert.notDeepEqual(await ledger.apply('other', 'sale', 123), first); // scope is tenant+key

  // Ledger: concurrent applies dedupe (same receipt, one entry).
  const ledger2 = new Ledger();
  const [ca, cb] = await Promise.all([ledger2.apply('t', 'k', 10), ledger2.apply('t', 'k', 10)]);
  assert.equal(cb, ca);
  assert.equal(ledger2.entries.length, 1);

  // Service: Transient after commit -> retry same receipt, single debit.
  const ledger3 = new Ledger();
  const acks3 = [];
  let fails = 2;
  const service3 = new PaymentService(ledger3, {
    acknowledge: async r => { acks3.push(r); if (fails-- > 0) throw new Transient('flaky'); },
  });
  const r3 = await service3.pay('shop', 'sale', 123, 3);
  assert.equal(ledger3.entries.length, 1);
  assert.equal(acks3.length, 3);
  assert.ok(acks3.every(a => a === r3), 'same receipt forwarded each retry');

  // Service: non-Transient errors are not retried.
  const ledger4 = new Ledger();
  let acks4 = 0;
  const boom = new Error('boom');
  const service4 = new PaymentService(ledger4, { acknowledge: async () => { acks4++; throw boom; } });
  await assert.rejects(() => service4.pay('shop', 'sale', 123), e => e === boom);
  assert.equal(acks4, 1);
  assert.equal(ledger4.entries.length, 1);

  // Service: attempts bounds retries; final Transient preserved by identity.
  const ledger5 = new Ledger();
  const acks5 = [];
  const killer = new Transient('down');
  const service5 = new PaymentService(ledger5, {
    acknowledge: async r => { acks5.push(r); throw killer; },
  });
  await assert.rejects(() => service5.pay('shop', 'sale', 123, 3), e => e === killer);
  assert.equal(acks5.length, 3);
  assert.equal(ledger5.entries.length, 1);
  const ledger5b = new Ledger();
  let acks5b = 0;
  const service5b = new PaymentService(ledger5b, { acknowledge: async () => { acks5b++; throw new Transient(); } });
  await assert.rejects(() => service5b.pay('shop', 'sale', 123, 1), Transient);
  assert.equal(acks5b, 1);

  // Service: validation happens before any ledger/transport action.
  const seen = { applied: 0, acked: 0 };
  const spyLedger = { apply: async () => { seen.applied++; return { id: 1, tenant: 'x', key: 'y', cents: 1 }; } };
  const spyTransport = { acknowledge: async () => { seen.acked++; } };
  const spy = new PaymentService(spyLedger, spyTransport);
  for (const args of [['', 'k', 5], ['t', '', 5], ['t', 'k', 0], ['t', 'k', -5], ['t', 'k', 1.5],
    ['t', 'k', 5, 0], ['t', 'k', 5, 6], ['t', 'k', 5, 2.5], ['t', 'k', 5, 3.0 - 2.5]]) {
    await assert.rejects(() => spy.pay(...args), e => e instanceof Error && e.message === 'invalid payment');
  }
  assert.equal(seen.applied, 0);
  assert.equal(seen.acked, 0);
  const ok = await spy.pay('t', 'k', 5); // attempts defaults to 3
  assert.deepEqual(ok, { id: 1, tenant: 't', key: 'k', cents: 5 });

  // Service: repeated call across pays returns original receipt; concurrent pays dedupe.
  const ledger6 = new Ledger();
  const service6 = new PaymentService(ledger6, { acknowledge: async () => {} });
  const r6 = await service6.pay('shop', 'sale', 9);
  assert.equal(await service6.pay('shop', 'sale', 9), r6);
  await assert.rejects(() => service6.pay('shop', 'sale', 12), e => e instanceof Error && e.message === 'key conflict');
  const [r7, r8] = await Promise.all([service6.pay('shop', 'other', 9), service6.pay('shop', 'other', 9)]);
  assert.equal(r8, r7);
  assert.equal(ledger6.entries.length, 2); // 'sale' + single 'other'
}
module.exports = main();
EOF
